class Solution {
public:
    int maxTotalReward(vector<int>& rewardValues) {
        sort(rewardValues.begin(), rewardValues.end());
        int mx = rewardValues.back();
        int W = 2 * mx + 1, words = (W + 63) / 64;
        vector<unsigned long long> dp(words, 0ULL);
        dp[0] = 1ULL;
        for (int v : rewardValues) {
            auto nd = dp;
            int fw = v / 64, rm = v % 64;
            for (int w = 0; w <= fw && w < words; w++) {
                unsigned long long lo = dp[w];
                if (w == fw && rm) lo &= (1ULL << rm) - 1;
                if (!lo) continue;
                int tw = w + fw;
                if (tw < words) {
                    nd[tw] |= rm ? (lo << rm) : lo;
                    if (rm && tw + 1 < words) nd[tw + 1] |= lo >> (64 - rm);
                }
            }
            dp = move(nd);
        }
        for (int b = W - 1; b >= 0; b--)
            if ((dp[b / 64] >> (b % 64)) & 1ULL) return b;
        return 0;
    }
};

