class Solution {
    public int maxTotalReward(int[] rewardValues) {
        Arrays.sort(rewardValues);
        int mx = rewardValues[rewardValues.length - 1];
        int W = 2 * mx + 1, words = (W + 63) / 64;
        long[] dp = new long[words];
        dp[0] = 1L;
        for (int v : rewardValues) {
            long[] nd = dp.clone();
            int fw = v / 64, rm = v % 64;
            for (int w = 0; w <= fw && w < words; w++) {
                long lo = dp[w];
                if (w == fw && rm != 0) lo &= (1L << rm) - 1;
                if (lo == 0) continue;
                int tw = w + fw;
                if (tw < words) {
                    nd[tw] |= (rm == 0) ? lo : (lo << rm);
                    if (rm != 0 && tw + 1 < words) nd[tw + 1] |= lo >>> (64 - rm);
                }
            }
            dp = nd;
        }
        for (int b = W - 1; b >= 0; b--)
            if (((dp[b / 64] >>> (b % 64)) & 1L) != 0) return b;
        return 0;
    }
}

