class Solution:
    def maxTotalReward(self, rewardValues):
        rewardValues.sort()
        m = rewardValues[-1]
        dp = [False] * (2 * m + 1)
        dp[0] = True
        for v in rewardValues:
            for x in range(min(v, 2 * m - v + 1)):
                if dp[x]:
                    dp[x + v] = True
        for x in range(2 * m, -1, -1):
            if dp[x]:
                return x
        return 0

