        sort(rewardValues.begin(), rewardValues.end());
        int m = rewardValues.back();
        vector<char> dp(2 * m + 1, 0);
        dp[0] = 1;
        for (int v : rewardValues)
            for (int x = 0; x < v && x + v <= 2 * m; x++)
                if (dp[x]) dp[x + v] = 1;
        for (int x = 2 * m; x >= 0; x--)
            if (dp[x]) return x;
        return 0;
    }
};

